import React, { useState } from 'react';
import { CCodeBlock, IconRefresh } from '@cloud-materials/common';

const codeObj = {
  AvailableMonitor: {
    AffectCount: 1,
    AffectDurationMilliSecond: 1000,
    AffectTimeItems: [
      {
        BeginTime: '2023-09-18 11:41:21.941',
        EndTime: '2023-09-18 11:41:22.941',
      },
    ],
    CheckConfig: {
      CheckIntervalMilliSecond: 1000,
      EnableStatUnavailableTime: true,
    },
  },
};

export default () => {
  const [data, setData] = useState<string | string[]>([
    'ss\nddd\ndddddd\nghasdfasdiiiiiiiiiiiiiiiiiiiiiiiiiii iiiiiii iiiiiiiiiiiiiiiiiiiiiiiif\nqqqqqq\nddddd\nzzzzz\nsssss\nhhhhhh\njjjjjj\nffffff\nlllll\niiiii\noooooo',
    'asdfasdfsa',
  ]);
  const [loading, setLoading] = useState(false);

  return (
    <div>
      <CCodeBlock
        data={data}
        operationGroup={[
          { type: 'download' },
          { type: 'copy' },
          {
            render: <IconRefresh />,
            popoverContent: '刷新',
            onClick: async () => {
              await new Promise<void>(resolve => {
                setLoading(true);

                setTimeout(() => {
                  setData([
                    'aaa\ndbbb\nccc\nghasdfasdf\nqqqqqq\nddddd\nzzzzz\nsssss\nhhhhhh\njjjjjj\nffffff\nlllll\niiiii\noooooo',
                    'ggg',
                  ]);
                  resolve();
                }, 1000);
              }).then(() => {
                setLoading(false);
              });
            },
          },
        ]}
        tabTitles={['tab1', 'tab2']}
        title={'我是标题'}
        selectOptions={['java', 'typescript', 'c', 'ruby']}
        arcoSelectProps={{ placeholder: 'c' }}
        loading={loading}
      />
      <br />
      <br />
      <CCodeBlock
        data={JSON.stringify(codeObj, null, 4)}
        operationGroup={[{ type: 'download' }, { type: 'copy' }]}
        // title={'我是标题'}
        // selectOptions={['java', 'typescript', 'c', 'ruby']}
        style={{ width: '600px' }}
      />
      <br />
      <br />
      <p>空态</p>
      <div style={{ height: 300 }}>
        <CCodeBlock data={[]} loading={loading} style={{ width: '600px', height: '100%' }} />
      </div>
    </div>
  );
};

